import {stochasticK,RULE_TEXT} from './stoch-strategy.js';
import {macdFeatures} from './macd.js';
const mean=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:null;
const sma=(a,n)=>a.length>=n?mean(a.slice(-n)):null;
const pct=(value,reference)=>Number.isFinite(value)&&Number.isFinite(reference)&&reference!==0?(value/reference-1)*100:null;
function ema(a,n){if(a.length<n)return null;let e=mean(a.slice(0,n)),k=2/(n+1);for(let i=n;i<a.length;i++)e=a[i]*k+e*(1-k);return e;}
export function rsi(a,n=14){if(a.length<=n)return null;let gain=0,loss=0;for(let i=1;i<=n;i++){let d=a[i]-a[i-1];gain+=Math.max(d,0);loss+=Math.max(-d,0)}gain/=n;loss/=n;for(let i=n+1;i<a.length;i++){let d=a[i]-a[i-1];gain=(gain*(n-1)+Math.max(d,0))/n;loss=(loss*(n-1)+Math.max(-d,0))/n}return loss===0?(gain===0?50:100):100-100/(1+gain/loss);}
export function candleFeatures(candles){if(!candles.length)return {};const c=candles.at(-1),closes=candles.map(c=>c.close),tr=candles.map((c,i)=>i?Math.max(c.high-c.low,Math.abs(c.high-candles[i-1].close),Math.abs(c.low-candles[i-1].close)):c.high-c.low),atr=sma(tr,14),m20=sma(closes,20),m50=sma(closes,50),m200=sma(closes,200),window=closes.slice(-20),sd=window.length===20?Math.sqrt(mean(window.map(v=>(v-m20)**2))):null,upper=sd===null?null:m20+2*sd,lower=sd===null?null:m20-2*sd,priorVolume=candles.slice(-21,-1).map(c=>c.volume),range=c.high-c.low;
let peak=Math.max(...candles.slice(-20).map(c=>c.high)),low=Math.min(...candles.slice(-20).map(c=>c.low));
return {...macdFeatures(candles),availableBars:candles.length,referenceClosedAt:c.time+14400,stochastic14K:stochasticK(candles),rsi14:rsi(closes),rsi14Change3:closes.length>17?rsi(closes)-rsi(closes.slice(0,-3)):null,atr14:atr,atrPct:atr===null?null:pct(c.close+atr,c.close),sma20:m20,sma50:m50,sma200:m200,closeAboveSma50:m50===null?null:c.close>m50,closeAboveSma200:m200===null?null:c.close>m200,ema20:ema(closes,20),ema50:ema(closes,50),sma50Slope5Pct:closes.length>=55?pct(m50,sma(closes.slice(0,-5),50)):null,closeDistanceSma20Pct:pct(c.close,m20),closeDistanceSma50Pct:pct(c.close,m50),closeDistanceSma200Pct:pct(c.close,m200),bollingerWidthPct:m20&&sd!==null?(upper-lower)/m20*100:null,bollingerPosition:sd===0?.5:sd===null?null:(c.close-lower)/(upper-lower),volumeRatio20:priorVolume.length===20&&mean(priorVolume)>0?c.volume/mean(priorVolume):null,candleBodyPct:pct(c.close,c.open),upperWickFraction:range>0?(c.high-Math.max(c.open,c.close))/range:0,lowerWickFraction:range>0?(Math.min(c.open,c.close)-c.low)/range:0,closePosition:range>0?(c.close-c.low)/range:.5,return4hPct:closes.length>1?pct(c.close,closes.at(-2)):null,return24hPct:closes.length>6?pct(c.close,closes.at(-7)):null,return7dPct:closes.length>42?pct(c.close,closes.at(-43)):null,range20Pct:pct(peak,low)};}
const row=c=>[c.time,c.open,c.high,c.low,c.close,c.volume];
export function analyzeTrade(past,candles,index,signal,trade){const entry=trade.entryPrice,features=candleFeatures(past),line=typeof signal.lineFormula==='function'?signal.lineFormula(past.length):null,last=past.at(-1),atr=features.atr14;let lastTouch=(signal.touches||[]).at(-1);let after=candles.slice(index),observed=trade.exitTime===null?after:after.filter(c=>trade.exitAtOpen?c.time<trade.exitTime:c.time<=trade.exitTime);let high=observed.length?Math.max(...observed.map(c=>c.high)):entry,low=observed.length?Math.min(...observed.map(c=>c.low)):entry;
return {analysisVersion:1,entryFeatures:{...features,entryDistanceTrendPct:pct(entry,line),entryDistanceConfirmationPct:pct(entry,signal.confirmationPrice),entryGapPct:pct(entry,last.close),stopAtrRatio:null,targetAtrRatio:atr>0?entry*.05/atr:null,trendAgeDays:signal.trendAgeDays,trendAgeBars:signal.trendAgeBars,touchCount:signal.majorTouchCount,trendDropPct:pct(line,signal.startPrice),barsSinceLastTouch:lastTouch?past.length-lastTouch.index:null,breakoutVolumeRatio:signal.volumeRatio,isHighVolume:signal.isHighVolume,isRetest:signal.isRetest,logScale:signal.logScale},outcomeFeatures:{directionalMaximumFavorablePct:trade.side==='SHORT'?100*(1-low/entry):100*(high/entry-1),directionalMaximumAdversePct:trade.side==='SHORT'?100*(1-high/entry):100*(low/entry-1),observedBars:observed.length,maximumHighReturnPct:pct(high,entry),maximumLowReturnPct:pct(low,entry),returnAfter1BarPct:after.length>=1?pct(after[0].close,entry):null,returnAfter3BarsPct:after.length>=3?pct(after[2].close,entry):null,returnAfter6BarsPct:after.length>=6?pct(after[5].close,entry):null,returnAfter12BarsPct:after.length>=12?pct(after[11].close,entry):null},context:{columns:['unixSeconds','open','high','low','close','volume'],before:past.slice(-80).map(row),after:after.slice(0,80).map(row)},trend:{priceAtEntry:line,priceAtConfirmation:signal.breakoutPrice,startPrice:signal.startPrice,touches:signal.touches}};}
export function benchmarkFeatures(candles,entryTime){let before=candles.filter(c=>c.time+14400<=entryTime).slice(-499);return candleFeatures(before);}
export function makeExport(state,portfolio){const taken=new Map(portfolio.ledger.map(t=>[t.key,t]));const trades=state.trades.map(t=>({...t,entryMode:state.entryMode||t.entryMode||'baseline',portfolioOutcome:taken.has(t.key)?taken.get(t.key).status:'SKIPPED',portfolioPnl:taken.get(t.key)?.pnl??null,portfolioBalance:taken.get(t.key)?.balanceAfter??null}));return {schema:'tradingly-trade-analysis-v1',exportedAt:new Date().toISOString(),strategy:{assetUniverse:'crypto-only',universeVersion:state.universeVersion||'crypto-only-v1',entryMode:state.entryMode||'baseline',additionalEntryRule:RULE_TEXT,timeframe:'4H',directions:['LONG','SHORT'],shortEntryRule:RULE_TEXT,shortPnlRule:'positionUsd * (1 - exitPrice/entryPrice) minus fees; funding and liquidation not modeled',initialBalance:state.portfolioSettings?.initialBalance??500,positionPct:state.portfolioSettings?.positionPct??100,riskPct:null,tpPct:5,slPct:null,rr:null,feePctPerSide:state.portfolioSettings?.feePct??0,oneOpenPosition:true,simultaneousPriority:'entryTime, then range20Pct ascending, then symbol alphabetical, then side',maxHoldDays:7,modelVersion:state.strategyVersion,openPositionRule:'TP or exit at 168h closing price; first new signal at or after exit; incomplete periods marked at final close'},run:{startDate:state.startDate,endDate:state.endDate,source:state.source,complete:state.complete,createdAt:state.createdAt,finishedAt:state.finishedAt,benchmark:state.benchmark,featureCoverage:{withEntryFeatures:trades.filter(t=>t.entryFeatures).length,total:trades.length}},portfolio:{...portfolio,ledger:portfolio.ledger.map(({context,...t})=>t)},tasks:state.tasks,trades,notes:['All timestamps are UTC Unix seconds; display timezone is Europe/Istanbul.','Entry features use closed candles only; outcomeFeatures and after context are future data and must not be used as entry filters.','Open and ambiguous signals are separate classes. Portfolio assumptions are not the same as signal labels.','Partial runs and unavailable histories can bias comparisons.','Maximum high/low include the complete exit candle, whose intrabar order is unknown.','This experimental rule was selected by searching historical outcomes. The X10 result of215TP/222signals was selected on the supplied257-signal historical sample; it is not independent validation or a future guarantee.']};}
export function makeCsv(data){const featureKeys=[...new Set(data.trades.flatMap(t=>Object.keys(t.entryFeatures||{})))].sort(),btcKeys=['rsi14','atrPct','return24hPct','closeAboveSma50','closeAboveSma200'];const columns=['symbol','exchange','timeframe','entryTime','signalTime','entryPrice','tp','sl','status','exitTime','exitPrice','portfolioOutcome','portfolioPnl','portfolioBalance','returnPct','deadline','entryMode','confirm_coinTrend','confirm_high10','confirm_btc4h','confirm_macd','confirm_ma50Macd',...featureKeys.map(k=>'entry_'+k),...btcKeys.map(k=>'btc_'+k),'side'];const quote=v=>v===null||v===undefined?'':typeof v==='string'?'"'+v.replaceAll('"','""')+'"':String(v);const rows=data.trades.map(t=>[...columns.slice(0,16).map(k=>t[k]),t.entryMode||data.strategy?.entryMode||'baseline',t.confirmations?.coinTrend,t.confirmations?.high10,t.confirmations?.btc4h,t.confirmations?.macd,t.confirmations?.ma50Macd,...featureKeys.map(k=>t.entryFeatures?.[k]),...btcKeys.map(k=>t.benchmarkFeatures?.[k]),t.side||'LONG']);return '\uFEFF'+[columns,...rows].map(r=>r.map(quote).join(',')).join('\r\n');}
